class Solution {
    static int solution(int n) {
        String s = String.valueOf(n);
        int sum = 0;
        for (int i = 0; i < s.length(); i++)
            sum += (i % 2 == 0 ? 1 : -1) * (s.charAt(i) - '0');
        return sum;
    }
}

